64			archive:         selfConsistent.archive,
65		})
66		// 作业 3：取消，只残留实际输入。
67		writeSyntheticRecord(t, dir, &storedJob{
68			id: 3, submitter: "a", requestID: "c3", seed: 6,
69			values:          []int64{9},
70			queuedAt:        base.Add(4 * time.Second),
71			finishedAt:      base.Add(5 * time.Second),
72			status:          StatusCanceled,
73			effectiveValues: []int64{9},
74		})
75		// 作业 4：失败（无上游、BlockerID 0 的自身失败），只残留归档。
76		writeSyntheticRecord(t, dir, &storedJob{
77			id: 4, submitter: "bob", requestID: "f4", seed: -1,
78			values:     []int64{1, 2, 3},
79			queuedAt:   base.Add(6 * time.Second),
80			finishedAt: base.Add(7 * time.Second),
81			status:     StatusFailed, failureReason: "平方和超出 int64 范围", blockerID: 0,
82			archive: selfConsistent.archive,
83		})
84		// 作业 5：取消，既无归档也无实际输入（无残留——不应被改写，见另案）。
85		writeSyntheticRecord(t, dir, &storedJob{
86			id: 5, submitter: "a", requestID: "c5",
87			values:     []int64{8},
88			queuedAt:   base.Add(8 * time.Second),
89			finishedAt: base.Add(9 * time.Second),
90			status:     StatusCanceled,
91		})
92	
93		s, err := Open(dir)
94		if err != nil {
95			t.Fatal(err)
96		}
97		defer s.Close()
98	
99		g2 := mustGet(t, s, 2)
100		if g2.Status != StatusFailed || g2.FailureReason != failedReason || g2.BlockerID != 9 {
101			t.Fatalf("作业 2 终态/原因/根因被改动: status=%s reason=%q blocker=%d",
102				g2.Status, g2.FailureReason, g2.BlockerID)
103		}
104		if g2.Archive != nil || g2.EffectiveValues != nil {
105			t.Fatalf("作业 2 不得返回残留归档与实际输入: archive=%+v eff=%v",
106				g2.Archive, g2.EffectiveValues)
107		}
108		assertInt64s(t, "job2 原始整数保留", g2.Values, []int64{5, -3})
109		assertUint64s(t, "job2 有序依赖保留", g2.Dependencies, []uint64{1})
110		if g2.Seed != 4 || g2.RequestID != "f2" || g2.Submitter != "a" {
111			t.Fatalf("作业 2 提交参数被改动: %+v", g2)
112		}
113		if !g2.FinishedAt.Equal(base.Add(3*time.Second)) ||
114			!g2.StartedAt.Equal(base.Add(2*time.Second+time.Millisecond)) ||
115			!g2.QueuedAt.Equal(base.Add(2*time.Second)) {
116			t.Fatalf("作业 2 已有时间被改动: queued=%s started=%s finished=%s",
117				g2.QueuedAt, g2.StartedAt, g2.FinishedAt)
118		}
119	
120		g3 := mustGet(t, s, 3)
121		if g3.Status != StatusCanceled || g3.BlockerID != 0 || g3.FailureReason != "" {
122			t.Fatalf("作业 3 取消状态被改判: %+v", g3)
123		}
124		if g3.Archive != nil || g3.EffectiveValues != nil {
125			t.Fatalf("作业 3 不得返回残留实际输入: archive=%+v eff=%v",
126				g3.Archive, g3.EffectiveValues)
127		}
128	
129		g4 := mustGet(t, s, 4)
130		if g4.Status != StatusFailed || g4.BlockerID != 0 ||
131			g4.FailureReason != "平方和超出 int64 范围" {
132			t.Fatalf("作业 4 失败判定被改写: %+v", g4)
133		}
134		if g4.Archive != nil || g4.EffectiveValues != nil {
135			t.Fatalf("作业 4 不得返回残留归档: archive=%+v eff=%v",
136				g4.Archive, g4.EffectiveValues)
137		}
138		assertInt64s(t, "job4 原始整数保留", g4.Values, []int64{1, 2, 3})
139	
140		g5 := mustGet(t, s, 5)
141		if g5.Status != StatusCanceled || g5.Archive != nil || g5.EffectiveValues != nil {
142			t.Fatalf("作业 5 应保持无残留的取消状态: %+v", g5)
143		}
144	
145		// 按提交人与时间范围列举与按作业号读取一致：不带任何成功产物。
146		listed, err := s.List("a", base.Add(1500*time.Millisecond), base.Add(9500*time.Millisecond))
147		if err != nil {
148			t.Fatal(err)
149		}
150		seen := map[uint64]*Job{}
151		for _, j := range listed {
152			seen[j.ID] = j
153			if j.Archive != nil || j.EffectiveValues != nil {
154				t.Fatalf("列举中的作业 %d 带出了成功产物: archive=%+v eff=%v",
155					j.ID, j.Archive, j.EffectiveValues)
156			}
157		}
158		for _, id := range []uint64{2, 3, 5} {
159			if seen[id] == nil || seen[id].Status != mustGet(t, s, id).Status {
160				t.Fatalf("列举缺少或状态不一致的作业 %d: %+v", id, seen[id])
161			}
162		}
163		if seen[4] != nil {
164			t.Fatalf("作业 4 属于 bob，不应出现在 a 的列举中")
165		}
166	
167		// 清理真正落盘：磁盘记录不再含归档与实际输入，终态与原因保留。
168		for _, id := range []uint64{2, 3, 4} {
169			r := readOnDiskRecord(t, filepath.Join(dir, jobFileName(id)))
170			if r.Archive != nil || len(r.EffectiveValues) != 0 {
171				t.Fatalf("作业 %d 磁盘记录仍有成功产物: archive=%+v eff=%v",
172					id, r.Archive, r.EffectiveValues)
173			}
174		}
175		r2 := readOnDiskRecord(t, filepath.Join(dir, jobFileName(2)))
176		if r2.Status != StatusFailed || r2.FailureReason != failedReason || r2.BlockerID != 9 {
177			t.Fatalf("作业 2 落盘终态被改写: status=%s reason=%q blocker=%d",
178				r2.Status, r2.FailureReason, r2.BlockerID)
179		}
180		assertInt64s(t, "job2 落盘原始整数保留", r2.Values, []int64{5, -3})
181	
182		// 合法成功记录不受清理影响。
183		g1 := mustGet(t, s, 1)
184		if g1.Status != StatusSucceeded || g1.Archive == nil || g1.Archive.Sum != 2 {
185			t.Fatalf("合法成功记录不应受影响: %+v", g1)
186		}
187	}
188	
189	// 再次打开仍然干净：上一次打开清理并落盘后，第二次打开读到的终态记录依旧
190	// 不含归档与实际输入，也不会触发任何新的改判。
191	func TestReopenCleanedTerminalRecordsStayCleanOnSecondOpen(t *testing.T) {
192		dir := t.TempDir()
193		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
194		a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
195		writeSyntheticRecord(t, dir, &storedJob{
196			id: 2, submitter: "a", requestID: "f2",
197			values:   []int64{5},
198			queuedAt: base, finishedAt: base.Add(time.Second),
199			status: StatusFailed, failureReason: "旧失败原因",
200			effectiveValues: []int64{5},
201			archive:         a.archive,
202		})
203		s1, err := Open(dir)
204		if err != nil {
205			t.Fatal(err)
206		}
207		if g := mustGet(t, s1, 2); g.Archive != nil || g.EffectiveValues != nil {
208			t.Fatalf("首次打开即应清理: %+v", g)
209		}
210		if err := s1.Close(); err != nil {
211			t.Fatal(err)
212		}
213		s2, err := Open(dir)
214		if err != nil {
215			t.Fatal(err)
216		}
217		defer s2.Close()
218		g := mustGet(t, s2, 2)
219		if g.Status != StatusFailed || g.FailureReason != "旧失败原因" ||
220			g.Archive != nil || g.EffectiveValues != nil {
221			t.Fatalf("第二次打开应仍是无成功产物的原失败状态: %+v", g)
222		}
223	}
224	
225	// 同一提交人用原非空请求号再次提交相同内容：返回原终态作业的当前详情，同样
226	// 不含成功归档与实际输入，不重算、不创建另一份作业；内容不同仍是原有的幂等
227	// 冲突。请求号仍属于原作业，新请求才取后续作业号。
228	func TestReplayTerminalRecordKeepsTerminalAndNoArtifacts(t *testing.T) {
229		dir := t.TempDir()
230		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
231		a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
232		writeSyntheticRecord(t, dir, &storedJob{
233			id: 2, submitter: "a", requestID: "f2", seed: 4,
234			values:   []int64{5, -3},
235			queuedAt: base, finishedAt: base.Add(time.Second),
236			status: StatusFailed, failureReason: "旧失败原因", blockerID: 0,
237			effectiveValues: []int64{5, -3},
238			archive:         a.archive,
239		})
240		s, err := Open(dir)
241		if err != nil {
242			t.Fatal(err)
243		}
244		defer s.Close()
245	
246		// 相同内容 → 原终态详情，无错误。
247		replay, err := s.Submit(SubmitRequest{
248			Submitter: "a", RequestID: "f2", Values: []int64{5, -3}, Seed: 4,
249		})
250		if err != nil || replay.ID != 2 {
251			t.Fatalf("幂等重放应返回原作业: id=%d err=%v", replayID(replay), err)
252		}
253		if replay.Status != StatusFailed || replay.FailureReason != "旧失败原因" ||
254			replay.Archive != nil || replay.EffectiveValues != nil {
255			t.Fatalf("重放返回必须是无成功产物的原终态详情: %+v", replay)
256		}
257		// 不另建作业、不重算：目录中仍只有作业 2 的记录，新请求取下一个作业号 3。
258		entries, err := os.ReadDir(dir)
259		if err != nil {
260			t.Fatal(err)
261		}
262		for _, e := range entries {
263			if e.IsDir() || e.Name() == jobFileName(2) || strings.HasPrefix(e.Name(), ".tmp-") {
264				continue
265			}
266			t.Fatalf("幂等重放不应产生新记录文件: %s", e.Name())
267		}
268		if g := mustGet(t, s, 2); g.Status != StatusFailed {
269			t.Fatalf("重放后原作业不得被重算: %s", g.Status)
270		}
271		// 内容不同 → 原有的幂等冲突，返回的原作业视图同样干净。
272		conflict, err := s.Submit(SubmitRequest{
273			Submitter: "a", RequestID: "f2", Values: []int64{5}, Seed: 4,
274		})
275		if !errors.Is(err, ErrIdempotencyConflict) || conflict == nil || conflict.ID != 2 {
276			t.Fatalf("内容不一致须返回幂等冲突: view=%+v err=%v", conflict, err)
277		}
278		if conflict.Archive != nil || conflict.EffectiveValues != nil {
279			t.Fatalf("冲突返回的原作业视图不得带成功产物: %+v", conflict)
280		}
281		// 全新请求取未消耗的下一个作业号并正常计算。
282		fresh := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
283		if fresh.ID != 3 {
284			t.Fatalf("新作业应取得 3 号（重放不消耗作业号），got %d", fresh.ID)
285		}
286		waitStatus(t, s, 3, StatusSucceeded)
287	}
288	
289	// 等待这些终态作业的下游继续遵守既有阻断规则，不能利用残留结果开始计算；
290	// 根因沿合法依赖链保留为终态作业自身。
291	func TestDownstreamOfCleanedTerminalJobsStillBlocked(t *testing.T) {
292		dir := t.TempDir()
293		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
294		a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
295		// 作业 1：失败但残留自洽归档；作业 2：取消但残留实际输入。
296		writeSyntheticRecord(t, dir, &storedJob{
297			id: 1, submitter: "a", requestID: "f1",
298			values:   []int64{7},
299			queuedAt: base, finishedAt: base.Add(time.Second),
300			status: StatusFailed, failureReason: "作业 1 的旧失败原因",
301			effectiveValues: []int64{7},
302			archive:         a.archive,
303		})
304		writeSyntheticRecord(t, dir, &storedJob{
305			id: 2, submitter: "a", requestID: "c2",
306			values:   []int64{4},
307			queuedAt: base.Add(time.Second), finishedAt: base.Add(2 * time.Second),
308			status:          StatusCanceled,
309			effectiveValues: []int64{4},
310		})
311		// 作业 3 排队等待 1，作业 4 排队等待 3（多跳），作业 5 排队等待 2。
312		for _, q := range []struct {
313			id  uint64
314			dep uint64
315		}{{3, 1}, {4, 3}, {5, 2}} {
316			writeSyntheticRecord(t, dir, &storedJob{
317				id: q.id, submitter: "a", requestID: "q" + itoa(q.id),
318				values:       []int64{1},
319				dependencies: []uint64{q.dep},
320				queuedAt:     base.Add(time.Duration(q.id) * time.Second),
321				status:       StatusQueued,
322			})
323		}
324	
325		s, err := Open(dir)
326		if err != nil {
327			t.Fatal(err)
328		}
329		defer s.Close()
330	
331		g3 := waitStatus(t, s, 3, StatusFailed)
332		if g3.BlockerID != 1 || g3.Archive != nil || g3.EffectiveValues != nil ||
333			!g3.StartedAt.IsZero() {
334			t.Fatalf("作业 3 须按既有规则被失败上游阻断且从不计算: %+v", g3)
335		}
336		g4 := waitStatus(t, s, 4, StatusFailed)
337		if g4.BlockerID != 1 {
338			t.Fatalf("作业 4 的根因须沿链条保留为作业 1: blocker=%d", g4.BlockerID)
339		}
340		g5 := waitStatus(t, s, 5, StatusFailed)
341		if g5.BlockerID != 2 {
342			t.Fatalf("作业 5 须被已取消的作业 2 阻断: blocker=%d", g5.BlockerID)
343		}
344		// 上游终态记录本身的原因不被下游级联改写。
345		if g1 := mustGet(t, s, 1); g1.FailureReason != "作业 1 的旧失败原因" || g1.Archive != nil {
346			t.Fatalf("作业 1 原失败原因与清理结果须保留: %+v", g1)
347		}
348		if g2 := mustGet(t, s, 2); g2.Status != StatusCanceled || g2.Archive != nil {
349			t.Fatalf("作业 2 取消状态须保留且无归档: %+v", g2)
350		}
351		// 阻断结果同样落盘。
352		if b := onDiskBlocker(t, dir, 4); b != 1 {
353			t.Fatalf("作业 4 落盘根因=%d want 1", b)
354		}
355	}
356	
357	// 原始整数序列属于提交参数：已失败记录即使原始序列为空，也只清理成功产物，
358	// 不补造参数、不清空（本来就空）其他字段，也不把终态改判成排队记录的
359	// “原始整数序列为空”失败。
360	func TestFailedRecordWithEmptyOriginalValuesKeepsTerminal(t *testing.T) {
361		dir := t.TempDir()
362		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
363		a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
364		writeSyntheticRecord(t, dir, &storedJob{
365			id: 1, submitter: "a", requestID: "f1",
366			queuedAt: base, finishedAt: base.Add(time.Second),
367			status: StatusFailed, failureReason: "计算被中断：归档上次关闭时作业仍在运行",
368			effectiveValues: []int64{7, 8},
369			archive:         a.archive,
370		})
371		s, err := Open(dir)
372		if err != nil {
373			t.Fatal(err)
374		}
375		defer s.Close()
376		g := mustGet(t, s, 1)
377		if g.Status != StatusFailed {
378			t.Fatalf("终态必须保留: %s", g.Status)
379		}
380		if g.FailureReason != "计算被中断：归档上次关闭时作业仍在运行" {
381			t.Fatalf("失败原因不能换成排队记录的空序列原因等新理由: %q", g.FailureReason)
382		}
383		if len(g.Values) != 0 {
384			t.Fatalf("空原始序列属于提交参数，不应被补造: %v", g.Values)
385		}
386		if g.Archive != nil || g.EffectiveValues != nil {
387			t.Fatalf("残留成功产物必须清空: archive=%+v eff=%v", g.Archive, g.EffectiveValues)
388		}
389		r := readOnDiskRecord(t, filepath.Join(dir, jobFileName(1)))
390		if r.Archive != nil || len(r.EffectiveValues) != 0 || len(r.Values) != 0 {
391			t.Fatalf("落盘记录应无成功产物且不补造原始参数: %+v", r)
392		}
393	}
394	
395	// 没有任何残留的失败/取消记录与合法成功记录不触发恢复改写：磁盘字节保持
396	// 原样（不补写完成时间，不规范化任何字段）。
397	func TestCleanTerminalAndSucceededRecordsAreNotRewritten(t *testing.T) {
398		dir := t.TempDir()
399		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
400		syntheticSucceededRecord(t, dir, 1, []int64{2}, []int64{2}, nil, base)
401		writeSyntheticRecord(t, dir, &storedJob{
402			id: 2, submitter: "a", requestID: "f2",
403			values:   []int64{5},
404			queuedAt: base.Add(2 * time.Second), finishedAt: base.Add(3 * time.Second),
405			status: StatusFailed, failureReason: "旧失败原因",
406		})
407		writeSyntheticRecord(t, dir, &storedJob{
408			id: 3, submitter: "a", requestID: "c3",
409			values:   []int64{9},
410			queuedAt: base.Add(4 * time.Second), finishedAt: base.Add(5 * time.Second),
411			status: StatusCanceled,
412		})
413		before := map[uint64][]byte{}
414		for _, id := range []uint64{1, 2, 3} {
415			data, err := os.ReadFile(filepath.Join(dir, jobFileName(id)))
416			if err != nil {
417				t.Fatal(err)
418			}
419			before[id] = data
420		}
421	
422		s, err := Open(dir)
423		if err != nil {
424			t.Fatal(err)
425		}
426		defer s.Close()
427		for _, id := range []uint64{1, 2, 3} {
428			after, rerr := os.ReadFile(filepath.Join(dir, jobFileName(id)))
429			if rerr != nil {
430				t.Fatal(rerr)
431			}
432			if !bytes.Equal(before[id], after) {
433				t.Fatalf("无残留的作业 %d 记录不应被恢复改写", id)
434			}
435		}
436	}
437	
438	// 残留清理遵守“恢复出的记录写回读入时文件名”：非默认命名的终态记录在原
439	// 文件上被原子替换，不按作业号另写默认命名记录而同号旧记录原样保留。
440	func TestCleanedTerminalRecordWithSuffixedFileNameUpdatesSameFile(t *testing.T) {
441		dir := t.TempDir()
442		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
443		a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
444		j := &storedJob{
445			id: 2, submitter: "a", requestID: "f2",
446			values:   []int64{5},
447			queuedAt: base, finishedAt: base.Add(time.Second),
448			status: StatusFailed, failureReason: "旧失败原因",
449			effectiveValues: []int64{5},
450			archive:         a.archive,
451			fileName:        suffixedRecordName(2),
452		}
453		data, err := encodeRecord(j)
454		if err != nil {
455			t.Fatal(err)
456		}
457		custom := suffixedRecordName(2)
458		if err := writeFileAtomic(dir, custom, data, 0o600); err != nil {
459			t.Fatal(err)
460		}
461	
462		s, err := Open(dir)
463		if err != nil {
464			t.Fatal(err)
465		}
466		defer s.Close()
467		g := mustGet(t, s, 2)
468		if g.Status != StatusFailed || g.FailureReason != "旧失败原因" ||
469			g.Archive != nil || g.EffectiveValues != nil {
470			t.Fatalf("非默认命名的失败记录应在保留终态的前提下清理: %+v", g)
471		}
472		r := readOnDiskRecord(t, filepath.Join(dir, custom))
473		if r.Archive != nil || len(r.EffectiveValues) != 0 || r.Status != StatusFailed {
474			t.Fatalf("清理必须写回原文件: %+v", r)
475		}
476		assertNoDefaultRecord(t, dir, 2)
477	}
