// 本文件覆盖“重新打开归档时清理已失败或已取消终态记录中残留的成功产物”：
// 只有成功作业才提供完整归档，保存状态已经是失败或取消、且记录能按现有规则
// 正常解析的作业，其记录里残留的实际参与计算输入与成功归档（即使数值、摘要、
// 日志与校验值全部自洽）都不能在重开后再被按作业号读取或按提交人列举带出。
// 清理只移除成功产物：终态、失败原因、阻断根因、作业号、提交人、请求号、
// 原始整数及次序、种子、有序依赖与已有时间一律保留。

// readOnDiskRecord 直接解析目录中某份记录文件，用于断言恢复改写真正落盘。
func readOnDiskRecord(t *testing.T, path string) *jobRecord {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var r jobRecord
	if err := json.Unmarshal(data, &r); err != nil {
		t.Fatal(err)
	}
	return &r
}

// 规格主例：失败记录残留全套自洽归档与实际输入，取消记录分别残留“归档+实际
// 输入”“只有实际输入”“只有归档”。重开后四类记录都只呈现原终态：成功归档与
// 实际输入一律为空，残留的总和、平方和、日志、摘要与校验值都取不到；终态、
// 原因、根因与提交参数原样保留，清理结果写回各自的原记录文件。
func TestReopenTerminalRecordsDropResidualSuccessArtifacts(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)

	// 一份数值层面完全自洽的成功归档（[5,2] → 总和 7、平方和 29），把它
	// 残留到失败/取消记录上：即使全套自洽也不能成为恢复为成功的依据。
	selfConsistent := buildSucceededJob(t, 1, []int64{5}, []int64{5, 2}, []uint64{1}, base)
	if selfConsistent.archive.Sum != 7 || selfConsistent.archive.SumOfSquares != 29 {
		t.Fatalf("premise: residual archive sum=%d sq=%d want 7,29",
			selfConsistent.archive.Sum, selfConsistent.archive.SumOfSquares)
	}
	// 作业 1：合法成功记录（[2] → 2），供作业 2 声明有序依赖。
	syntheticSucceededRecord(t, dir, 1, []int64{2}, []int64{2}, nil, base)

	// 作业 2：失败（因上游问题失败的既有原因，根因作业 9），残留归档+实际输入。
	failedReason := "直接上游作业 9 已失败，阻断本作业继续计算（其失败原因：旧根因）"
	writeSyntheticRecord(t, dir, &storedJob{
		id: 2, submitter: "a", requestID: "f2", seed: 4,
		values:       []int64{5, -3},
		dependencies: []uint64{1},
		queuedAt:     base.Add(2 * time.Second),
		startedAt:    base.Add(2*time.Second + time.Millisecond),
		finishedAt:   base.Add(3 * time.Second),
		status:       StatusFailed, failureReason: failedReason, blockerID: 9,
		effectiveValues: []int64{5, -3, 2},
		archive:         selfConsistent.archive,
	})
	// 作业 3：取消，只残留实际输入。
	writeSyntheticRecord(t, dir, &storedJob{
		id: 3, submitter: "a", requestID: "c3", seed: 6,
		values:          []int64{9},
		queuedAt:        base.Add(4 * time.Second),
		finishedAt:      base.Add(5 * time.Second),
		status:          StatusCanceled,
		effectiveValues: []int64{9},
	})
	// 作业 4：失败（无上游、BlockerID 0 的自身失败），只残留归档。
	writeSyntheticRecord(t, dir, &storedJob{
		id: 4, submitter: "bob", requestID: "f4", seed: -1,
		values:     []int64{1, 2, 3},
		queuedAt:   base.Add(6 * time.Second),
		finishedAt: base.Add(7 * time.Second),
		status:     StatusFailed, failureReason: "平方和超出 int64 范围", blockerID: 0,
		archive: selfConsistent.archive,
	})
	// 作业 5：取消，既无归档也无实际输入（无残留——不应被改写，见另案）。
	writeSyntheticRecord(t, dir, &storedJob{
		id: 5, submitter: "a", requestID: "c5",
		values:     []int64{8},
		queuedAt:   base.Add(8 * time.Second),
		finishedAt: base.Add(9 * time.Second),
		status:     StatusCanceled,
	})

	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()

	g2 := mustGet(t, s, 2)
	if g2.Status != StatusFailed || g2.FailureReason != failedReason || g2.BlockerID != 9 {
		t.Fatalf("作业 2 终态/原因/根因被改动: status=%s reason=%q blocker=%d",
			g2.Status, g2.FailureReason, g2.BlockerID)
	}
	if g2.Archive != nil || g2.EffectiveValues != nil {
		t.Fatalf("作业 2 不得返回残留归档与实际输入: archive=%+v eff=%v",
			g2.Archive, g2.EffectiveValues)
	}
	assertInt64s(t, "job2 原始整数保留", g2.Values, []int64{5, -3})
	assertUint64s(t, "job2 有序依赖保留", g2.Dependencies, []uint64{1})
	if g2.Seed != 4 || g2.RequestID != "f2" || g2.Submitter != "a" {
		t.Fatalf("作业 2 提交参数被改动: %+v", g2)
	}
	if !g2.FinishedAt.Equal(base.Add(3*time.Second)) ||
		!g2.StartedAt.Equal(base.Add(2*time.Second+time.Millisecond)) ||
		!g2.QueuedAt.Equal(base.Add(2*time.Second)) {
		t.Fatalf("作业 2 已有时间被改动: queued=%s started=%s finished=%s",
			g2.QueuedAt, g2.StartedAt, g2.FinishedAt)
	}

	g3 := mustGet(t, s, 3)
	if g3.Status != StatusCanceled || g3.BlockerID != 0 || g3.FailureReason != "" {
		t.Fatalf("作业 3 取消状态被改判: %+v", g3)
	}
	if g3.Archive != nil || g3.EffectiveValues != nil {
		t.Fatalf("作业 3 不得返回残留实际输入: archive=%+v eff=%v",
			g3.Archive, g3.EffectiveValues)
	}

	g4 := mustGet(t, s, 4)
	if g4.Status != StatusFailed || g4.BlockerID != 0 ||
		g4.FailureReason != "平方和超出 int64 范围" {
		t.Fatalf("作业 4 失败判定被改写: %+v", g4)
	}
	if g4.Archive != nil || g4.EffectiveValues != nil {
		t.Fatalf("作业 4 不得返回残留归档: archive=%+v eff=%v",
			g4.Archive, g4.EffectiveValues)
	}
	assertInt64s(t, "job4 原始整数保留", g4.Values, []int64{1, 2, 3})

	g5 := mustGet(t, s, 5)
	if g5.Status != StatusCanceled || g5.Archive != nil || g5.EffectiveValues != nil {
		t.Fatalf("作业 5 应保持无残留的取消状态: %+v", g5)
	}

	// 按提交人与时间范围列举与按作业号读取一致：不带任何成功产物。
	listed, err := s.List("a", base.Add(1500*time.Millisecond), base.Add(9500*time.Millisecond))
	if err != nil {
		t.Fatal(err)
	}
	seen := map[uint64]*Job{}
	for _, j := range listed {
		seen[j.ID] = j
		if j.Archive != nil || j.EffectiveValues != nil {
			t.Fatalf("列举中的作业 %d 带出了成功产物: archive=%+v eff=%v",
				j.ID, j.Archive, j.EffectiveValues)
		}
	}
	for _, id := range []uint64{2, 3, 5} {
		if seen[id] == nil || seen[id].Status != mustGet(t, s, id).Status {
			t.Fatalf("列举缺少或状态不一致的作业 %d: %+v", id, seen[id])
		}
	}
	if seen[4] != nil {
		t.Fatalf("作业 4 属于 bob，不应出现在 a 的列举中")
	}

	// 清理真正落盘：磁盘记录不再含归档与实际输入，终态与原因保留。
	for _, id := range []uint64{2, 3, 4} {
		r := readOnDiskRecord(t, filepath.Join(dir, jobFileName(id)))
		if r.Archive != nil || len(r.EffectiveValues) != 0 {
			t.Fatalf("作业 %d 磁盘记录仍有成功产物: archive=%+v eff=%v",
				id, r.Archive, r.EffectiveValues)
		}
	}
	r2 := readOnDiskRecord(t, filepath.Join(dir, jobFileName(2)))
	if r2.Status != StatusFailed || r2.FailureReason != failedReason || r2.BlockerID != 9 {
		t.Fatalf("作业 2 落盘终态被改写: status=%s reason=%q blocker=%d",
			r2.Status, r2.FailureReason, r2.BlockerID)
	}
	assertInt64s(t, "job2 落盘原始整数保留", r2.Values, []int64{5, -3})

	// 合法成功记录不受清理影响。
	g1 := mustGet(t, s, 1)
	if g1.Status != StatusSucceeded || g1.Archive == nil || g1.Archive.Sum != 2 {
		t.Fatalf("合法成功记录不应受影响: %+v", g1)
	}
}

// 再次打开仍然干净：上一次打开清理并落盘后，第二次打开读到的终态记录依旧
// 不含归档与实际输入，也不会触发任何新的改判。
func TestReopenCleanedTerminalRecordsStayCleanOnSecondOpen(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
	a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
	writeSyntheticRecord(t, dir, &storedJob{
		id: 2, submitter: "a", requestID: "f2",
		values:   []int64{5},
		queuedAt: base, finishedAt: base.Add(time.Second),
		status: StatusFailed, failureReason: "旧失败原因",
		effectiveValues: []int64{5},
		archive:         a.archive,
	})
	s1, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	if g := mustGet(t, s1, 2); g.Archive != nil || g.EffectiveValues != nil {
		t.Fatalf("首次打开即应清理: %+v", g)
	}
	if err := s1.Close(); err != nil {
		t.Fatal(err)
	}
	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	g := mustGet(t, s2, 2)
	if g.Status != StatusFailed || g.FailureReason != "旧失败原因" ||
		g.Archive != nil || g.EffectiveValues != nil {
		t.Fatalf("第二次打开应仍是无成功产物的原失败状态: %+v", g)
	}
}

// 同一提交人用原非空请求号再次提交相同内容：返回原终态作业的当前详情，同样
// 不含成功归档与实际输入，不重算、不创建另一份作业；内容不同仍是原有的幂等
// 冲突。请求号仍属于原作业，新请求才取后续作业号。
func TestReplayTerminalRecordKeepsTerminalAndNoArtifacts(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
	a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
	writeSyntheticRecord(t, dir, &storedJob{
		id: 2, submitter: "a", requestID: "f2", seed: 4,
		values:   []int64{5, -3},
		queuedAt: base, finishedAt: base.Add(time.Second),
		status: StatusFailed, failureReason: "旧失败原因", blockerID: 0,
		effectiveValues: []int64{5, -3},
		archive:         a.archive,
	})
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()

	// 相同内容 → 原终态详情，无错误。
	replay, err := s.Submit(SubmitRequest{
		Submitter: "a", RequestID: "f2", Values: []int64{5, -3}, Seed: 4,
	})
	if err != nil || replay.ID != 2 {
		t.Fatalf("幂等重放应返回原作业: id=%d err=%v", replayID(replay), err)
	}
	if replay.Status != StatusFailed || replay.FailureReason != "旧失败原因" ||
		replay.Archive != nil || replay.EffectiveValues != nil {
		t.Fatalf("重放返回必须是无成功产物的原终态详情: %+v", replay)
	}
	// 不另建作业、不重算：目录中仍只有作业 2 的记录，新请求取下一个作业号 3。
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, e := range entries {
		if e.IsDir() || e.Name() == jobFileName(2) || strings.HasPrefix(e.Name(), ".tmp-") {
			continue
		}
		t.Fatalf("幂等重放不应产生新记录文件: %s", e.Name())
	}
	if g := mustGet(t, s, 2); g.Status != StatusFailed {
		t.Fatalf("重放后原作业不得被重算: %s", g.Status)
	}
	// 内容不同 → 原有的幂等冲突，返回的原作业视图同样干净。
	conflict, err := s.Submit(SubmitRequest{
		Submitter: "a", RequestID: "f2", Values: []int64{5}, Seed: 4,
	})
	if !errors.Is(err, ErrIdempotencyConflict) || conflict == nil || conflict.ID != 2 {
		t.Fatalf("内容不一致须返回幂等冲突: view=%+v err=%v", conflict, err)
	}
	if conflict.Archive != nil || conflict.EffectiveValues != nil {
		t.Fatalf("冲突返回的原作业视图不得带成功产物: %+v", conflict)
	}
	// 全新请求取未消耗的下一个作业号并正常计算。
	fresh := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{1}})
	if fresh.ID != 3 {
		t.Fatalf("新作业应取得 3 号（重放不消耗作业号），got %d", fresh.ID)
	}
	waitStatus(t, s, 3, StatusSucceeded)
}

// 等待这些终态作业的下游继续遵守既有阻断规则，不能利用残留结果开始计算；
// 根因沿合法依赖链保留为终态作业自身。
func TestDownstreamOfCleanedTerminalJobsStillBlocked(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
	a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
	// 作业 1：失败但残留自洽归档；作业 2：取消但残留实际输入。
	writeSyntheticRecord(t, dir, &storedJob{
		id: 1, submitter: "a", requestID: "f1",
		values:   []int64{7},
		queuedAt: base, finishedAt: base.Add(time.Second),
		status: StatusFailed, failureReason: "作业 1 的旧失败原因",
		effectiveValues: []int64{7},
		archive:         a.archive,
	})
	writeSyntheticRecord(t, dir, &storedJob{
		id: 2, submitter: "a", requestID: "c2",
		values:   []int64{4},
		queuedAt: base.Add(time.Second), finishedAt: base.Add(2 * time.Second),
		status:          StatusCanceled,
		effectiveValues: []int64{4},
	})
	// 作业 3 排队等待 1，作业 4 排队等待 3（多跳），作业 5 排队等待 2。
	for _, q := range []struct {
		id  uint64
		dep uint64
	}{{3, 1}, {4, 3}, {5, 2}} {
		writeSyntheticRecord(t, dir, &storedJob{
			id: q.id, submitter: "a", requestID: "q" + itoa(q.id),
			values:       []int64{1},
			dependencies: []uint64{q.dep},
			queuedAt:     base.Add(time.Duration(q.id) * time.Second),
			status:       StatusQueued,
		})
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()

	g3 := waitStatus(t, s, 3, StatusFailed)
	if g3.BlockerID != 1 || g3.Archive != nil || g3.EffectiveValues != nil ||
		!g3.StartedAt.IsZero() {
		t.Fatalf("作业 3 须按既有规则被失败上游阻断且从不计算: %+v", g3)
	}
	g4 := waitStatus(t, s, 4, StatusFailed)
	if g4.BlockerID != 1 {
		t.Fatalf("作业 4 的根因须沿链条保留为作业 1: blocker=%d", g4.BlockerID)
	}
	g5 := waitStatus(t, s, 5, StatusFailed)
	if g5.BlockerID != 2 {
		t.Fatalf("作业 5 须被已取消的作业 2 阻断: blocker=%d", g5.BlockerID)
	}
	// 上游终态记录本身的原因不被下游级联改写。
	if g1 := mustGet(t, s, 1); g1.FailureReason != "作业 1 的旧失败原因" || g1.Archive != nil {
		t.Fatalf("作业 1 原失败原因与清理结果须保留: %+v", g1)
	}
	if g2 := mustGet(t, s, 2); g2.Status != StatusCanceled || g2.Archive != nil {
		t.Fatalf("作业 2 取消状态须保留且无归档: %+v", g2)
	}
	// 阻断结果同样落盘。
	if b := onDiskBlocker(t, dir, 4); b != 1 {
		t.Fatalf("作业 4 落盘根因=%d want 1", b)
	}
}

// 原始整数序列属于提交参数：已失败记录即使原始序列为空，也只清理成功产物，
// 不补造参数、不清空（本来就空）其他字段，也不把终态改判成排队记录的
// “原始整数序列为空”失败。
func TestFailedRecordWithEmptyOriginalValuesKeepsTerminal(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
	a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
	writeSyntheticRecord(t, dir, &storedJob{
		id: 1, submitter: "a", requestID: "f1",
		queuedAt: base, finishedAt: base.Add(time.Second),
		status: StatusFailed, failureReason: "计算被中断：归档上次关闭时作业仍在运行",
		effectiveValues: []int64{7, 8},
		archive:         a.archive,
	})
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	g := mustGet(t, s, 1)
	if g.Status != StatusFailed {
		t.Fatalf("终态必须保留: %s", g.Status)
	}
	if g.FailureReason != "计算被中断：归档上次关闭时作业仍在运行" {
		t.Fatalf("失败原因不能换成排队记录的空序列原因等新理由: %q", g.FailureReason)
	}
	if len(g.Values) != 0 {
		t.Fatalf("空原始序列属于提交参数，不应被补造: %v", g.Values)
	}
	if g.Archive != nil || g.EffectiveValues != nil {
		t.Fatalf("残留成功产物必须清空: archive=%+v eff=%v", g.Archive, g.EffectiveValues)
	}
	r := readOnDiskRecord(t, filepath.Join(dir, jobFileName(1)))
	if r.Archive != nil || len(r.EffectiveValues) != 0 || len(r.Values) != 0 {
		t.Fatalf("落盘记录应无成功产物且不补造原始参数: %+v", r)
	}
}

// 没有任何残留的失败/取消记录与合法成功记录不触发恢复改写：磁盘字节保持
// 原样（不补写完成时间，不规范化任何字段）。
func TestCleanTerminalAndSucceededRecordsAreNotRewritten(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
	syntheticSucceededRecord(t, dir, 1, []int64{2}, []int64{2}, nil, base)
	writeSyntheticRecord(t, dir, &storedJob{
		id: 2, submitter: "a", requestID: "f2",
		values:   []int64{5},
		queuedAt: base.Add(2 * time.Second), finishedAt: base.Add(3 * time.Second),
		status: StatusFailed, failureReason: "旧失败原因",
	})
	writeSyntheticRecord(t, dir, &storedJob{
		id: 3, submitter: "a", requestID: "c3",
		values:   []int64{9},
		queuedAt: base.Add(4 * time.Second), finishedAt: base.Add(5 * time.Second),
		status: StatusCanceled,
	})
	before := map[uint64][]byte{}
	for _, id := range []uint64{1, 2, 3} {
		data, err := os.ReadFile(filepath.Join(dir, jobFileName(id)))
		if err != nil {
			t.Fatal(err)
		}
		before[id] = data
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	for _, id := range []uint64{1, 2, 3} {
		after, rerr := os.ReadFile(filepath.Join(dir, jobFileName(id)))
		if rerr != nil {
			t.Fatal(rerr)
		}
		if !bytes.Equal(before[id], after) {
			t.Fatalf("无残留的作业 %d 记录不应被恢复改写", id)
		}
	}
}

// 残留清理遵守“恢复出的记录写回读入时文件名”：非默认命名的终态记录在原
// 文件上被原子替换，不按作业号另写默认命名记录而同号旧记录原样保留。
func TestCleanedTerminalRecordWithSuffixedFileNameUpdatesSameFile(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
	a := buildSucceededJob(t, 1, []int64{7}, []int64{7}, nil, base)
	j := &storedJob{
		id: 2, submitter: "a", requestID: "f2",
		values:   []int64{5},
		queuedAt: base, finishedAt: base.Add(time.Second),
		status: StatusFailed, failureReason: "旧失败原因",
		effectiveValues: []int64{5},
		archive:         a.archive,
		fileName:        suffixedRecordName(2),
	}
	data, err := encodeRecord(j)
	if err != nil {
		t.Fatal(err)
	}
	custom := suffixedRecordName(2)
	if err := writeFileAtomic(dir, custom, data, 0o600); err != nil {
		t.Fatal(err)
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s.Close()
	g := mustGet(t, s, 2)
	if g.Status != StatusFailed || g.FailureReason != "旧失败原因" ||
		g.Archive != nil || g.EffectiveValues != nil {
		t.Fatalf("非默认命名的失败记录应在保留终态的前提下清理: %+v", g)
	}
	r := readOnDiskRecord(t, filepath.Join(dir, custom))
	if r.Archive != nil || len(r.EffectiveValues) != 0 || r.Status != StatusFailed {
		t.Fatalf("清理必须写回原文件: %+v", r)
	}
	assertNoDefaultRecord(t, dir, 2)
}

package numeric

import "fmt"

// 本文件收拢“作业因直接上游结果不可用而失败”的判断与归因规则。运行期间
// （提交后级联、取消/失败传播）与重新打开归档（排队记录复查、已成功归档
// 复核）两处共用同一套规则，避免后续调整时两处说法不一致：
//
//  1. 选择直接阻断者：作业等待多个直接上游时，一律按提交时保存的依赖顺序
//     （storedJob.dependencies 的次序）选取最靠前的不可用上游，绝不按作业号
//     大小、完成先后或失败原因重新挑选。
//  2. 确定根因 BlockerID：沿选中的直接上游已有的阻断信息（blockerID）确定
//     根因——上游自身带根因时沿用，根因不因经过一个已归档的中间作业而重新
//     起算；上游没有根因记录时，以该上游自身作业号为根因；直接上游记录缺失
//     时以缺失的作业号为根因。
//  3. 构造失败原因：始终指出当前作业的直接上游；能取得上游自身失败原因时一并
//     附上；直接上游与根因不是同一作业时，再说明沿链条保留的根因作业号。
//
// 作业一旦据此进入失败状态，后续另一上游再失败或取消都不会重选直接阻断者、
// 改写原因或根因（调用方只对仍在排队/待复核的作业调用本文件的规则）。
//
// 三种场景对“不可用”的界定与措辞有必须保留的区别：
//   - 运行期间（含重开后排队记录遇到仍存在的失败/取消上游）：仅已失败或已
//     取消的上游阻断排队作业，原因表述为该上游“已失败/已被取消”；
//   - 重开归档时的排队记录：上游记录在目录中缺失也算不可用，以缺失作业号为
//     根因，并明确说明其结果无法使用；
//   - 重开归档时的成功记录：上游记录缺失、或恢复后未保持带完整归档的成功
//     状态都使成功结果不可用，原因表述为“成功结果不可用”。
//
// 若全部直接上游都存在且有效，仅本作业保存的追加输入与上游总和对不上，则属于
// 本作业自身归档错误（BlockerID 保持 0），由 firstAppendedMismatch 单独处理；
// 该核对只在没有不可用上游时进行，因此“追加输入不符”与“上游不可用”同时出现
// 时，仍归因给依赖顺序中最靠前的不可用上游。
//
// 依赖列表自身的合法性（重复引用同一作业号、引用作业号不小于本作业的作业）同样
// 属于本作业记录自身有误，与上游是否有效、数值结果是否自洽无关，在任何上游可用性
// 核对之前直接判失败，BlockerID 保持 0；被引用的有效上游不被改判。重开归档时排队
// 记录与成功记录通过同一个入口 invalidDependencyListReason 共用这条规则（检查顺序
// 与失败原因措辞完全一致），避免两处各自安排判断而在调整规则时遗漏某一种状态。
//
// 排队记录的原始整数序列为空（缺省、null 或空数组）同样是记录自身问题：提交时
// 即拒绝空序列，恢复时也不能凭已有实际输入或成功上游的总和补出原始参数后继续
// 计算，一律改判失败，BlockerID 保持 0。该检查排在依赖列表自身合法性检查之后、
// 上游可用性判断之前。

// upstreamBlocked 判断某直接上游在当前场景下是否阻断本作业。dep 为 nil 表示
// 归档目录中缺少该作业号的记录（仅重开归档可能出现）；返回 false 表示暂不能
// 据此判定失败——排队作业继续等待，成功记录则可继续核对追加输入。
type upstreamBlocked func(id uint64, dep *storedJob) bool

// runtimeUpstreamBlocked 是运行期间的判定：仅已失败/取消的上游阻断仍在排队的
// 下游；排队、运行中与已成功的上游都不阻断（继续等待）。运行期内存索引与已
// 接受记录一致，已接受的依赖不可能缺失，nil 视为不阻断。
func runtimeUpstreamBlocked(_ uint64, dep *storedJob) bool {
	return dep != nil && (dep.status == StatusFailed || dep.status == StatusCanceled)
}

// restoredQueuedUpstreamBlocked 是重开归档时对排队记录的判定：除已失败/取消
// 外，直接上游记录缺失同样使其不可能再变为可用，立即级联失败。
func restoredQueuedUpstreamBlocked(_ uint64, dep *storedJob) bool {
	return dep == nil || dep.status == StatusFailed || dep.status == StatusCanceled
}

// restoredArchiveUpstreamBlocked 是重开归档时对已成功记录的判定：直接上游记录
// 缺失，或恢复后未保持“带完整归档的成功状态”，其成功结果都不可继续使用。
func restoredArchiveUpstreamBlocked(_ uint64, dep *storedJob) bool {
	return dep == nil || dep.status != StatusSucceeded || dep.archive == nil
}

// pickBlockingUpstream 按作业保存的依赖顺序返回第一个不可用的直接上游。
// dep 为 nil 表示该作业号的记录缺失；没有不可用上游时 ok=false。选择只取决于
// 依赖列表中的先后，与作业号大小、完成先后、失败原因无关。
func pickBlockingUpstream(j *storedJob, byID map[uint64]*storedJob, blocked upstreamBlocked) (directID uint64, dep *storedJob, ok bool) {
	for _, id := range j.dependencies {
		d := byID[id]
		if blocked(id, d) {
			return id, d, true
		}
	}
	return 0, nil, false
}

// blockerRoot 沿选中的直接上游已有的阻断信息确定根因作业号：上游自身带有根因
// 时沿用（根因不随中间已归档作业重新起算）；上游没有根因记录、或直接上游记录
// 缺失时，以该直接上游作业号本身为根因。
func blockerRoot(dep *storedJob, directID uint64) uint64 {
	if dep != nil && dep.blockerID != 0 {
		return dep.blockerID
	}
	return directID
}

// runtimeBlockedHead 给出运行期间（以及重开排队记录遇到仍存在的失败/取消上游
// 时）原因的首句：直接上游已失败或已被取消。
func runtimeBlockedHead(dep *storedJob) string {
	state := "失败"
	if dep.status == StatusCanceled {
		state = "被取消"
	}
	return fmt.Sprintf("直接上游作业 %d 已%s，阻断本作业继续计算", dep.id, state)
}

// restoredMissingHead 给出重开排队记录遇到直接上游记录缺失时原因的首句：以缺失
// 的作业号为根因，并明确说明其结果无法使用。
func restoredMissingHead(directID uint64) string {
	return fmt.Sprintf(
		"直接上游作业 %d 无法使用：归档目录中缺少该作业的记录，其结果无法使用，阻断本作业继续计算",
		directID)
}

// restoredArchiveHead 给出重开已成功记录因直接上游结果失效而改判时原因的首句：
// 上游记录缺失或恢复后未保持带完整归档的成功状态，成功结果不可用。
func restoredArchiveHead(directID uint64) string {
	return fmt.Sprintf(
		"直接上游作业 %d 无法使用：不存在或恢复后未保持带完整归档的成功状态，成功结果不可用，阻断本作业继续计算",
		directID)
}

// blockedFailureReason 在首句 head 之后统一补齐归因尾部：附上直接上游自身的
// 失败原因（若有），并在直接上游与根因不同一时说明沿链条保留的根因作业号。
func blockedFailureReason(head string, dep *storedJob, directID, root uint64) string {
	reason := head
	if dep != nil && dep.status == StatusFailed && dep.failureReason != "" {
		reason += "（其失败原因：" + dep.failureReason + "）"
	}
	if root != directID {
		reason += fmt.Sprintf("；阻断根因为作业 %d", root)
	}
	return reason
}

// invalidDependencyListReason 是重开归档时判断依赖列表自身合法性的唯一入口，
// 排队记录复查与成功归档复核共用，返回记录自身有误时的失败原因；列表合法时
// 返回空串。两项检查的顺序与措辞对两类记录完全一致：
//
//  1. 重复引用（duplicateDependency）：同一作业号在列表里再次出现——不论相邻
//     还是隔着其他上游——都按重复依赖判失败，原因指出保存顺序中首次再次出现
//     的作业号。唯一性按作业号判断，与上游总和是否相同无关：两个不同上游都
//     得到 3 时各引用一次并不重复。
//  2. 先后关系（firstIllegalOrderingDependency）：只有没有重复时，才按保存的
//     原顺序找第一个不小于本作业号的依赖（引用自己或后来作业），说明它不能
//     作为本作业的上游。只判断每个作业号与本作业号的大小，不要求列表按作业号
//     排序，也不比较提交时间。
//
// 两种问题同时存在时保留重复依赖的失败原因（重复检查先行，先命中即返回）。
// 两项都属于记录自身有误：不取决于上游是否存在、是否成功，也不因本作业的
// 数值、日志与校验值全部自洽而放行；在任何上游可用性核对之前判定，
// BlockerID 保持 0，不把被引用且原本有效的上游判成失败或归因给它。
//
// 运行期间提交时的唯一性与先后关系由 validateDependencyShapeLocked 等提交校验
// 强制；本入口只服务于重新打开归档：已保存记录可能绕过提交校验（旧版本写入或
// 记录被改动），恢复时必须按与提交一致的规则改判失败。
func invalidDependencyListReason(j *storedJob) string {
	if dupID, dup := duplicateDependency(j); dup {
		return duplicateDependencyReason(dupID)
	}
	if badID, bad := firstIllegalOrderingDependency(j); bad {
		return illegalOrderingDependencyReason(badID, j.id)
	}
	return ""
}

// duplicateDependency 按作业保存的依赖顺序找出第一个再次出现的上游作业号
// （即该作业号第二次出现的位置；相邻重复与隔着其他上游的重复同样识别）。
// 唯一性按作业号判断，与上游总和是否相同无关：两个不同上游都得到 3 时各
// 引用一次并不重复。没有重复时 ok=false。
//
// 运行期间提交时的唯一性由 validateDependencyShapeLocked 强制；本函数只服务于
// 重新打开归档：已保存记录的依赖列表可能绕过提交校验（旧版本写入或记录被
// 改动），恢复时必须按与提交一致的规则拒绝重复引用。
func duplicateDependency(j *storedJob) (id uint64, ok bool) {
	seen := make(map[uint64]struct{}, len(j.dependencies))
	for _, id := range j.dependencies {
		if _, dup := seen[id]; dup {
			return id, true
		}
		seen[id] = struct{}{}
	}
	return 0, false
}

// duplicateDependencyReason 构造“依赖列表重复”的失败原因：明确说明依赖列表
// 重复引用，并指出首次再次出现的上游作业号。这属于本作业记录自身有误，
// 与上游是否有效无关——即使被重复引用的上游恢复后仍成功，也不把它判成
// 失败或归因给它，因此 BlockerID 保持 0。
func duplicateDependencyReason(id uint64) string {
	return fmt.Sprintf(
		"依赖列表重复：直接上游作业 %d 在依赖列表中再次出现，同一作业不能重复引用，成功结果不可用",
		id)
}

// firstIllegalOrderingDependency 按作业保存的依赖顺序找出第一个违反先后关系
// 的直接上游作业号：正常提交只能引用已经存在的作业，而作业号按接受先后递增，
// 因此直接上游作业号必须严格小于本作业号；引用自己（等于）或引用后来作业
// （大于）都不合法。不比较提交时间，也不要求依赖列表按作业号排序——只判断
// 每个作业号与本作业号的大小。没有违反时 ok=false。
//
// 与上游是否存在、是否成功无关：即使被引用的作业确实存在且已经成功，也不能
// 接受这种依赖。运行期间提交时由 validateDependencyShapeLocked 与
// validateDependenciesExistLocked（只能引用已存在作业，作业号又按接受先后递增）
// 共同强制；本函数只服务于重新打开归档：已保存记录可能绕过提交
// 校验（旧版本写入或记录被改动），恢复时必须按与提交一致的规则改判失败。
// 这属于本作业记录自身有误，BlockerID 保持 0，不把被引用的有效作业判成失败。
func firstIllegalOrderingDependency(j *storedJob) (id uint64, ok bool) {
	for _, id := range j.dependencies {
		if id >= j.id {
			return id, true
		}
	}
	return 0, false
}

// illegalOrderingDependencyReason 构造“依赖先后关系不合法”的失败原因：指出
// 保存的依赖顺序中第一个不合法的上游作业号，并说明它不能作为本作业的上游。
// BlockerID 保持 0——这是本作业记录自身有误，即使被引用的作业存在且成功也不
// 把它判成失败或归因给它。
func illegalOrderingDependencyReason(id, selfID uint64) string {
	return fmt.Sprintf(
		"依赖先后关系不合法：保存的依赖顺序中作业 %d 是第一个作业号不小于本作业 %d 的直接上游，作业号按接受先后递增，它不能作为本作业的上游，成功结果不可用",
		id, selfID)
}

// emptyOriginalValuesReason 构造“原始整数序列为空”的失败原因：恢复出的排队记录
// 原始整数序列缺省、为 null 或为空数组（不含任何原始整数）时使用。提交入口拒绝
// 空序列，恢复时必须遵守同一项输入要求：该作业不能开始运行，不能凭已有实际输入
// 或成功上游的总和补出原始参数。这属于本作业记录自身有误，BlockerID 保持 0，
// 不把任何上游判成失败或归因给它；[0]、[0,0] 等非空序列不受此规则影响
// （有效性不看总和是否为 0）。
func emptyOriginalValuesReason() string {
	return "原始整数序列为空：记录不包含任何原始整数，与提交时的校验一致，不能开始计算，也不能凭已有实际输入或成功上游的总和补出原始参数"
}

// firstAppendedMismatch 在全部直接上游都存在且有效时，按保存的依赖顺序逐项核对
// 实际输入的追加部分（原始序列之后的 len(dependencies) 个位置），返回第一个对
// 不上的位置对应的上游作业号与失败原因；逐项相等时 ok=false。负数、零以及不同
// 上游恰好同和都按位置判断，不要求上游总和互不相同。
//
// 这属于本作业自身归档有误：有效上游不受影响，BlockerID 保持 0。调用前须确认
// 没有不可用上游（否则应优先归因给最靠前的不可用上游），且作业已通过
// effectiveInputsCorrespond（追加部分长度恰为依赖数量）。
func firstAppendedMismatch(j *storedJob, byID map[uint64]*storedJob) (directID uint64, reason string, ok bool) {
	n := len(j.values)
	for _, id := range j.dependencies {
		if j.effectiveValues[n] != byID[id].archive.Sum {
			return id, fmt.Sprintf(
				"实际输入的追加部分与直接上游作业 %d 的总和无法对应（追加值须按保存的依赖顺序逐项等于各上游总和），成功结果不可用",
				id), true
		}
		n++
	}
	return 0, "", false
}

package numeric

// Ready 表示基线可以运行。
//
// 该函数保持向后兼容；数值作业与归档的入口为 [Open]。
func Ready() bool { return true }

package numeric

// 本文件收拢作业依赖两种写法（旧式单依赖字段 HasDependency/DependencyID 与
// 有序依赖列表 Dependencies）之间的相互换算，让提交内容比较、重新打开归档
// 与成功归档核对对同一份依赖内容保持同一种理解：
//
//   - 读方向（normalizeDependencies）：把两种写法统一为有序依赖列表——非空
//     列表优先并保持原次序；列表为空（含缺省）且单依赖启用时，退化为只含该
//     作业号的列表；两者皆无视为无依赖。未启用单依赖时单独填写的
//     DependencyID 不产生任何依赖，空列表也不会覆盖已启用的单依赖。
//   - 写方向（legacyDependencyFields）：由规范化后的有序列表推导记录与归档
//     中保留的旧式单依赖字段——有无依赖由列表是否为空决定，单依赖作业号取
//     列表首项（即最早追加其总和的上游）；列表为空时两个字段都是零值。
//
// 提交请求的格式校验（两种写法互斥、零与重复作业号）仍在提交路径上先行完成，
// 不属于这里的换算；已保存的记录与归档则允许两类字段同时出现，一律以非空
// 列表为实际依赖，不套用提交请求的互斥要求。重新打开归档时，记录顶层与内嵌
// 归档的依赖表示都按读方向换算恢复，归档的旧式单依赖字段随之重写为规范化
// 形式（是否有依赖、列表首项），使详情与内嵌归档对外返回一致的依赖信息；
// 成功归档复核只比较换算后的实际有序列表（逐项、按次序），旧字段的缺省、
// 零值或残留值不会单独成为归档失效的理由。

// normalizeDependencies 把“单依赖字段 + 有序依赖列表”统一为有序依赖列表。
// 返回值永远是新切片，调用方可安全持有；无依赖时返回 nil。
func normalizeDependencies(hasDependency bool, dependencyID uint64, dependencies []uint64) []uint64 {
	if len(dependencies) > 0 {
		return append([]uint64(nil), dependencies...)
	}
	if hasDependency {
		return []uint64{dependencyID}
	}
	return nil
}

// legacyDependencyFields 由规范化后的有序依赖列表推导旧式单依赖字段：
// 列表非空时 hasDependency 为 true、dependencyID 为列表首项；空列表对应
// 两个零值。
func legacyDependencyFields(dependencies []uint64) (hasDependency bool, dependencyID uint64) {
	if len(dependencies) == 0 {
		return false, 0
	}
	return true, dependencies[0]
}

