// 归档形态。
func writeSucceededRecordPatched(t *testing.T, dir string, j *storedJob, patch func(r *jobRecord)) {
	t.Helper()
	data, err := encodeRecord(j)
	if err != nil {
		t.Fatal(err)
	}
	var r jobRecord
	if err := json.Unmarshal(data, &r); err != nil {
		t.Fatal(err)
	}
	patch(&r)
	writeRawRecord(t, dir, j.id, &r)
}

