			})
		}
		writeQueuedRecordFile(t, dir, jobFileName(uint64(n+1)), &storedJob{
			id: uint64(n + 1), submitter: "a", values: []int64{1},
			queuedAt: base.Add(time.Second), status: StatusQueued,
		})
		start := time.Now()
		s, err := Open(dir)
		if err != nil { t.Fatal(err) }
		gap := time.Now().Sub(start)
		waitStatus(t, s, uint64(n+1), StatusSucceeded)
		t.Logf("n=%d open=%s drain=%s", n, gap, time.Since(start)-gap)
		s.Close()
	}
}
EOF
