diff --git a/numeric/record.go b/numeric/record.go
index 937415d..9260e50 100644
--- a/numeric/record.go
+++ b/numeric/record.go
@@ -268,6 +268,13 @@ func syncDir(dir string) {
 //     不同提交人使用相同请求号也合法。冲突时同样不启动计算、不改写任何
 //     原有记录，不因记录状态（含已失败/取消）、提交时间或文件排列挑选一条；
 //   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
+//   - 保存状态为排队、且能按现有规则正常解析的记录先清除残留的成功产物：实际
+//     参与计算的输入与旧成功归档（只残留其中一种或两者都有按同一规则处理），
+//     即使数值、摘要、日志与校验值全部自洽也不能让排队作业直接成为成功，更
+//     不能作为这次计算的输入来源。排队继续表示尚未取得本次成功结果；作业号、
+//     提交人、请求号、原始整数及次序、种子、有序依赖与已有时间均保留，清理不
+//     补完成时间，也不把原本合法的排队作业改判失败。清理在排队记录自身合法性
